import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Dict, Any, Sequence

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 512,
        'dropout_rate': 0.2,
        'num_filters': 128,
        'kernel_size': 7,
        'num_blocks': 4
    }

class ResidualBlock(nn.Module):
    features: int
    kernel_size: Sequence[int]
    @nn.compact
    def __call__(self, x):
        residual = x
        y = nn.Conv(features=self.features, kernel_size=self.kernel_size, padding='SAME')(x)
        y = nn.relu(y)
        y = nn.Conv(features=self.features, kernel_size=self.kernel_size, padding='SAME')(y)
        if residual.shape == y.shape: return nn.relu(residual + y)
        else: return nn.relu(nn.Conv(features=self.features, kernel_size=(1,))(residual) + y)

class DeeperCNN(nn.Module):
    d_output: int
    task_type: str
    num_filters: int
    kernel_size: int
    num_blocks: int
    hidden_dim: int
    dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        k_size = (self.kernel_size,)
        x = nn.Conv(features=self.num_filters, kernel_size=k_size, padding='SAME')(x)
        x = nn.relu(x)

        for _ in range(self.num_blocks):
            x = ResidualBlock(features=self.num_filters, kernel_size=k_size)(x)

        # Concatenate Global Average and Global Max Pooling
        pooled_avg = jnp.mean(x, axis=1)
        pooled_max = jnp.max(x, axis=1)
        x = jnp.concatenate([pooled_avg, pooled_max], axis=-1)

        x = nn.Dense(features=self.hidden_dim)(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)
        x = nn.Dense(features=self.d_output)(x)

        if self.task_type == "regression": return x.squeeze(-1)
        else: return x

class CNNNetworkWrapper:
    def __init__(self, **kwargs): self.network = DeeperCNN(**kwargs)
    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key}, dummy_input, deterministic=True)
        return variables['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic: return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None: rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False, rngs={'dropout': rng_key})

def create_network(hparams: Dict[str, Any]):
    return CNNNetworkWrapper(
        d_output=hparams.get("d_output"), task_type=hparams.get("task_type"),
        num_filters=hparams.get("num_filters"), kernel_size=hparams.get("kernel_size"),
        num_blocks=hparams.get("num_blocks"), hidden_dim=hparams.get("hidden_dim"),
        dropout_rate=hparams.get("dropout_rate")
    )
